  const states = new Map()
  const stats = new Map()
  let out = ''
  let allowed = 0
  let denied = 0
  for (const { tick, key } of events) {
    let best = null
    for (const prefix of routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    let blocker = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const id = `${p.name}\0${key}`
        if (!states.has(id)) states.set(id, makeState(p))
        return states.get(id)
      })
      list.forEach((p, i) => advance(p, sts[i], tick))
      const idx = list.findIndex((p, i) => !allows(p, sts[i]))
      if (idx >= 0) blocker = list[idx].name
      else list.forEach((p, i) => record(p, sts[i], tick))
    }
    const st = stats.get(key) ?? { a: 0, d: 0 }
    stats.set(key, st)
    if (blocker === null) { st.a++; allowed++ } else { st.d++; denied++ }
