function makeState(p) {
  return p.kind === 'bucket'
    ? { num: p.capacity * p.per, last: null }
    : { ticks: [] }
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    if (s.last !== null) {
      s.num += p.refill * (tick - s.last)
      const cap = p.capacity * p.per
      if (s.num > cap) s.num = cap
    }
    s.last = tick
  } else {
    const edge = tick - p.span
    s.ticks = s.ticks.filter((x) => x > edge)
  }
}

function allows(p, s) {
  return p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit
}

function record(p, s, tick) {
  if (p.kind === 'bucket') s.num -= p.per
  else s.ticks.push(tick)
}

export function run({ routes, events }, mode) {
  const states = new Map()
  const stats = new Map()
  let out = ''
  let allowed = 0
  let denied = 0
  for (const { tick, key } of events) {
    let best = null
    for (const prefix of routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    let blocker = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const id = `${p.name}\0${key}`
        if (!states.has(id)) states.set(id, makeState(p))
        return states.get(id)
      })
      list.forEach((p, i) => advance(p, sts[i], tick))
      const idx = list.findIndex((p, i) => !allows(p, sts[i]))
      if (idx >= 0) blocker = list[idx].name
      else list.forEach((p, i) => record(p, sts[i], tick))
    }
    const st = stats.get(key) ?? { a: 0, d: 0 }
    stats.set(key, st)
    if (blocker === null) { st.a++; allowed++ } else { st.d++; denied++ }
    if (mode === 'replay') out += blocker === null ? `${tick} ${key} allow\n` : `${tick} ${key} deny ${blocker}\n`
  }
  if (mode === 'summary') {
    const keys = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    for (const k of keys) out += `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}\n`
    out += `total allowed=${allowed} denied=${denied}\n`
  }
  return out
}
